 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    # Find a periodic stripe coordinate and the smallest period that assigns
    # every residue class consistently and covers the full cycle.
    candidates = []
    for orient, keyfn in [('row', lambda r,c:r), ('col', lambda r,c:c),
                          ('diag_down', lambda r,c:c-r), ('diag_up', lambda r,c:r+c)]:
        keys = [(keyfn(r,c),v) for r,c,v in pts]
        for p in range(1, max(h,w)+1):
            vals = {}
            ok = True
            for k,v in keys:
                q = k % p
                if q in vals and vals[q] != v:
                    ok = False
                    break
                vals[q] = v
            if ok and len(vals) == p:
                candidates.append((p, orient, keyfn, vals))
                break
    if not candidates:
        # Fallback: use smallest consistent period even if some phases are unseen.
        for orient, keyfn in [('row', lambda r,c:r), ('col', lambda r,c:c),
                              ('diag_down', lambda r,c:c-r), ('diag_up', lambda r,c:r+c)]:
            keys = [(keyfn(r,c),v) for r,c,v in pts]
            for p in range(1, max(h,w)+1):
                vals = {}
                ok = True
                for k,v in keys:
                    q=k%p
                    if q in vals and vals[q]!=v:
                        ok=False; break
                    vals[q]=v
                if ok:
                    candidates.append((p,orient,keyfn,vals))
                    break
    p, orient, keyfn, vals = min(candidates, key=lambda x:(x[0], ['row','col','diag_down','diag_up'].index(x[1])))
    # A fully observed period defines the repeating stripe pattern.
    return [[vals[keyfn(r,c) % p] for c in range(w)] for r in range(h)]
"
}

